# 3. Reading the text CSV into Pandas DataFrame
df = pd.read_csv(io.StringIO(csv_data))

# 4. Creating Hover Text for the Map (Updated to show 3 beers + types)
df['Hover_Text'] = (
    "<b>" + df['Brewery'] + "</b> (" + df['City'] + ", " + df['State'] + ")<br><br>" +
    "🥇 1. " + df['Beer1'] + "<br>" +
    "🥈 2. " + df['Beer2'] + "<br>" +
    "🥉 3. " + df['Beer3']
)

# 5. Map Visualization settings
fig = px.scatter_map(
    df, 
    lat="Lat", 
    lon="Lon", 
    hover_name="Brewery",
    hover_data={"Lat": False, "Lon": False, "Hover_Text": True, "State": False, "City": False, "Beer1": False, "Beer2": False, "Beer3": False},
    color_discrete_sequence=["#FFD700"], # Gold color for markers
    zoom=3.5, 
    height=750
)

# Styling markers and hover template
fig.update_traces(
    marker=dict(size=10, opacity=0.8, symbol='circle'),
    hovertemplate="%{hovertext}"
)

# Dark mode map style
fig.update_layout(map_style="carto-darkmatter", margin={"r":0,"t":0,"l":0,"b":0})

# 6. Output to screen
st.plotly_chart(fig, use_container_width=True)

st.subheader("📋 Detailed Brewery Database")
# Displaying the DataFrame as a sortable/searchable table (Added Beer3)
st.dataframe(
    df[['State', 'City', 'Brewery', 'Beer1', 'Beer2', 'Beer3']].sort_values(by=['State', 'City']), 
    use_container_width=True,
    hide_index=True
)
